// Replay of recorded jev-filter runs. Data: data.js (generated by benchmarks/showcase/render.py
// from real runs). One fixed 1280x720 stage, scaled to fit; ?capture=1 renders frames for GIFs.
(() => {
  const DATA = window.JEV_SHOWCASE;
  const params = new URLSearchParams(location.search);
  const CAPTURE = params.get('capture') === '1';
  const wanted = params.get('lang') || (/^zh/i.test(navigator.language) && !CAPTURE ? 'zh' : 'en');
  let lang = wanted === 'zh' ? 'zh' : 'en';
  let demo = Object.prototype.hasOwnProperty.call(DATA.demos, params.get('demo')) ? params.get('demo') : 'browse';
  let index = 0, phase = 1, timer = null, playing = !CAPTURE;

  const T = {
    en: {
      tabs: {browse: 'Browser', desktop: 'Desktop', survey: 'Survey'},
      lede: {
        browse: 'A real recorded run on the synthetic shop fixture: each step is one Jev request. The program lists the controls, Jev returns probabilities, the program re-checks the target and acts. The order button pauses until a person approves.',
        desktop: 'A real recorded run in a Windows Forms app through UI Automation: the same loop, then a destructive goal that stops before anything is deleted.',
        survey: 'One survey command over 2,000 generated support tickets: typed answers per record, aggregated in code. Accuracy is measured against the generator\'s ground truth.',
      },
      goal: 'Goal', step: 'Step', of: 'of', play: 'Play', pause: 'Pause',
      operation: 'Next operation', target: 'Target', among: 'among', controls: 'controls',
      request: 'one Jev request', value: 'Value (supplied by you)', irr: 'Irreversible?',
      gatePass: 'not a commit action → execute', guard: 'Target re-checked on a fresh observation before acting',
      paused: 'Paused', pauseWhy: 'before an irreversible action', rule: 'keyword rule', jevp: 'Jev',
      nothing: 'Nothing was clicked. The run returns', resume: 'Resume only after the user approves:',
      approved: 'Approved by the user', recheck: 'The program re-checks the page fingerprint, then clicks',
      done: 'done', verified: 'Verified on a fresh observation', contains: 'page text contains', containsWindow: 'window text contains',
      intro1: 'The program lists what can be clicked, typed or chosen.',
      intro2: 'Jev picks the next operation and its target, with probabilities. It never writes selectors, coordinates or text.',
      intro3: 'The program re-checks the target and acts. Pay, send and delete pause for you.',
      requests: 'Jev requests', tokens: 'input tokens', cost: 'input cost', time: 'run time (excl. start-up)', both: 'Totals for both goals', sec: 's', model: 'selectors or text written by Jev',
      tot: {req: 'requests', tok: 'tokens', usd: 'USD', t: 'time'},
      scene: 'Next goal', stopped: 'Stopped', hist: 'Executed so far',
      ops: {CLICK: 'CLICK', TYPE_TEXT: 'TYPE', SELECT: 'SELECT', SCROLL_DOWN: 'SCROLL', PRESS_ENTER: 'ENTER', PRESS_ESCAPE: 'ESC', SCROLL_UP: 'SCROLL UP', DONE: 'DONE', BLOCKED: 'BLOCKED', WAIT: 'WAIT', BACK: 'BACK'},
      recorded: 'Recorded', slide: 'Slide ', notes: 'Synthetic fixtures, live Jev (jev-1.13.0). Frames and probabilities are the recorded ones, not re-rendered. Reproduce: <code>python -m benchmarks.showcase.record --demo browse|desktop|survey</code>. Real-website results and limits: <a href="../../hosted-execution.html">hosted execution guide</a>.',
      sv: {records: 'records', kept: 'kept after screening', requests: 'Jev requests', time: 'wall time', usd: 'input cost', uncertain: 'uncertain', topic: 'Topic', sentiment: 'Sentiment', churn: 'Churn risk', byTopic: 'By topic', examples: 'Most confident examples, 3 largest topics', accuracy: 'Accuracy vs ground truth', levels: ['Angry', 'Neutral', 'Positive'], screen: 'Relevance screen', yes: 'say they may leave', calib: 'Uncalibrated until you pass --labels with your own labelled sample.', n: 'n', mean: 'mood (0–2)', churnShare: 'churn', sec: 's'},
    },
    zh: {
      tabs: {browse: '浏览器', desktop: '桌面', survey: '调研'},
      lede: {
        browse: '在合成商店夹具上真实录制的一次运行：每一步是一次 Jev 请求。程序列出可操作的控件，Jev 给出概率，程序重新核对目标后执行。下单按钮会暂停，等人确认。',
        desktop: '通过 UI Automation 在 Windows Forms 应用里真实录制：同样的循环；随后是一个破坏性目标，在删除前就停下。',
        survey: '一条 survey 命令处理 2000 条生成的客服工单：逐条类型化判断，由代码汇总。准确率对照生成器的真值计算。',
      },
      goal: '目标', step: '第', of: '步，共', play: '播放', pause: '暂停',
      operation: '下一步操作', target: '目标控件', among: '候选', controls: '个控件',
      request: '一次 Jev 请求', value: '填入的值（由你提供）', irr: '不可逆？',
      gatePass: '不是提交类动作 → 执行', guard: '执行前在最新观察上重新核对目标',
      paused: '已暂停', pauseWhy: '遇到不可逆动作', rule: '关键词规则', jevp: 'Jev',
      nothing: '什么都没点。运行返回', resume: '用户同意后才续跑：',
      approved: '用户已确认', recheck: '程序先核对页面指纹，再点击',
      done: '完成', verified: '在最新观察上校验通过', contains: '页面文字包含', containsWindow: '窗口文字包含',
      intro1: '程序列出可以点击、输入、选择的控件。',
      intro2: 'Jev 选出下一步操作和目标，并给出概率；它从不生成选择器、坐标或文字。',
      intro3: '程序重新核对目标后执行；付款、发送、删除类动作会停下来等你确认。',
      requests: '次 Jev 请求', tokens: '输入 token', cost: '输入费用', time: '运行时间（不含启动）', both: '两个目标合计', sec: '秒', model: 'Jev 写出的选择器或文字',
      tot: {req: '请求', tok: 'token', usd: '美元', t: '用时'},
      scene: '下一个目标', stopped: '已停止', hist: '已执行',
      ops: {CLICK: '点击', TYPE_TEXT: '输入', SELECT: '选择', SCROLL_DOWN: '滚动', PRESS_ENTER: '回车', PRESS_ESCAPE: 'Esc 键', SCROLL_UP: '上滚', DONE: '完成', BLOCKED: '受阻', WAIT: '等待', BACK: '返回'},
      recorded: '录制于', slide: '画面 ', notes: '合成夹具，真实 Jev（jev-1.13.0）。画面和概率都是录制时的原始数据，没有重新生成。复现：<code>python -m benchmarks.showcase.record --demo browse|desktop|survey</code>。真实网站上的结果与限制见<a href="../../hosted-execution.zh-CN.html">托管执行说明</a>。',
      sv: {records: '条记录', kept: '筛选后保留', requests: '次 Jev 请求', time: '总耗时', usd: '输入费用', uncertain: '条不确定', topic: '主题', sentiment: '情绪', churn: '流失风险', byTopic: '按主题交叉', examples: '置信度最高的样例（前 3 个主题）', accuracy: '对照真值的准确率', levels: ['愤怒', '中性', '正面'], screen: '相关性筛选', yes: '表示可能离开', calib: '在你用 --labels 提供自己的标注样本之前，阈值未经校准。', n: '条数', mean: '情绪均值（0–2）', churnShare: '流失', sec: '秒'},
    },
  };
  const t = () => T[lang];
  const $ = id => document.getElementById(id);
  const esc = s => String(s ?? '').replace(/[&<>"]/g, c => ({'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;'}[c]));
  const pct = p => (p == null ? '–' : Math.round(p * 100) + '%');
  const clean = s => String(s || '').replace(/^\[[^\]]+\]\s*/, '');
  const num = n => (n == null ? '–' : Number(n).toLocaleString('en-US'));

  function bars(items, chosen, cls) {
    return '<div class="bars">' + items.map(it => `<div class="row ${cls || ''} ${it.key === chosen ? 'on' : ''}">
      <span class="name" title="${esc(it.name)}">${esc(it.name)}</span>
      <span class="track"><span class="fill" style="width:${Math.max(1.5, (it.w ?? it.p) * 100)}%"></span></span>
      <span class="pct">${pct(it.p)}</span></div>`).join('') + '</div>';
  }

  function totals(s, d) {
    const x = s.totals || {};
    return `<div class="tot"><span><em>${t().tot.req}</em>${num(x.requests)}</span><span><em>${t().tot.tok}</em>${num(x.tokens)}</span>
      <span><em>${t().tot.usd}</em>$${(x.usd || 0).toFixed(4)}</span><span><em>${t().tot.t}</em>${((x.ms || 0) / 1000).toFixed(1)} ${t().sec}</span></div>`;
  }

  function timeline(d) {
    return '<div class="tl">' + d.slides.map((s, i) => {
      if (s.kind === 'intro' || s.kind === 'outro') return '';
      let c = i < index ? 'done' : i === index ? 'now' : '';
      if (s.kind === 'pause' && i <= index) c = 'pause';
      if (s.kind === 'done' && i <= index) c = 'ok';
      return `<i class="${c}"></i>`;
    }).join('') + '</div>';
  }

  function screen(d, s, overlay) {
    const img = d.images[s.frame];
    if (!img) return '';
    const maxW = 804, maxH = 500, isWeb = d.command === 'browse';
    const scale = Math.min(maxW / img.w, maxH / img.h);
    const w = Math.round(img.w * scale), h = Math.round(img.h * scale);
    const bar = isWeb
      ? `<div class="bar"><span class="dot"></span><span class="dot"></span><span class="dot"></span><span class="url">${esc(s.url || '')}</span></div>`
      : `<div class="bar"><span class="wtitle">${esc(s.title || '')}</span></div>`;
    let over = '';
    if (overlay && overlay.rect) {
      const r = overlay.rect, pad = 5;
      const x = r.x * scale - pad, y = r.y * scale - pad, bw = r.w * scale + 2 * pad, bh = r.h * scale + 2 * pad;
      over += `<div class="box ${overlay.red ? 'red' : ''}" style="left:${x}px;top:${y}px;width:${bw}px;height:${bh}px"></div>`;
      if (overlay.chip) {
        const above = y > 40, cy = above ? y - 36 : y + bh + 8;
        const cx = Math.min(Math.max(4, x), w - 330);
        over += `<div class="chip ${overlay.red ? 'red' : ''}" style="left:${cx}px;top:${cy}px">${overlay.chip}</div>`;
      }
    }
    if (overlay && overlay.banner) over += `<div class="banner ${overlay.bannerCls}">${overlay.banner}</div>`;
    return `<div class="win" style="width:${w + 2}px;margin:0 auto">${bar}<div class="shot" style="width:${w}px;height:${h}px">
      <img src="${d.dir}${s.frame}" width="${w}" height="${h}" alt="">${over}</div></div>`;
  }

  function history(d) {
    const done = d.slides.slice(0, index).filter(s => s.kind === 'step').slice(-5);
    if (!done.length) return '';
    return `<div class="hist"><p class="k">${t().hist}</p>` + done.map(s => `<p><b>${s.n}. ${esc(s.decide ? (t().ops[s.decide.operation] || s.decide.operation) : '✓')}</b>${esc(s.action.label)}${s.text ? ' ← “' + esc(s.text) + '”' : ''}</p>`).join('') + '</div>';
  }

  function opsItems(dec) {
    return dec.operations.slice(0, 4).map(o => ({key: o.op, name: t().ops[o.op] || o.op, p: o.p}));
  }

  function panel(d, s, ph) {
    const L = t();
    if (s.kind === 'step') {
      const dec = s.decide;
      let html = `<p class="k">${L.step} ${s.n} ${L.of} ${d.stepCount}${lang === 'zh' ? ' 步' : ''}</p>`;
      if (!dec) {
        return html + `<div class="big green">${L.approved}</div><p class="para">${L.recheck}: <b>${esc(s.action.label)}</b></p>
          <p class="check"><b>✓</b> ${L.guard}</p>`;
      }
      html += `<p class="meta">${L.request} · ${dec.latency_ms} ms · ${L.among} ${dec.candidates} ${L.controls}</p>`;
      html += `<p class="k">${L.operation}</p>` + bars(opsItems(dec), dec.operation);
      const tg = dec.targets || [];
      if (tg.length) html += `<p class="k">${L.target}</p>` + bars(tg.slice(0, 3).map((x, i) => ({key: i, name: clean(x.label), p: x.p})), 0, 't');
      if (s.text && dec.value) html += `<p class="k">${L.value}</p><p class="para"><span class="pill ok">${esc(dec.value)}</span>“${esc(s.text)}”</p>`;
      html += `<p class="check">${L.irr} <span class="pill ${dec.irreversible >= 0.5 ? 'bad' : ''}">${pct(dec.irreversible)}</span>${ph ? L.gatePass : ''}</p>`;
      if (ph) html += `<p class="check"><b>✓</b> ${L.guard}</p>`;
      return html + history(d);
    }
    if (s.kind === 'pause') {
      const why = [s.reason === 'label_rule' ? L.rule : null, s.irreversible_probability != null ? `${L.jevp} ${pct(s.irreversible_probability)}` : null].filter(Boolean).join(' + ');
      let html = `<p class="k">${L.paused}</p><div class="big red">⏸ ${esc(s.pending.label)}</div>`;
      if (s.decide) html += `<p class="k">${L.operation}</p>` + bars(opsItems(s.decide), s.decide.operation);
      html += `<p class="para">${L.pauseWhy}: <b>${esc(why)}</b></p><p class="para">${L.nothing} <span class="pill bad">needs_confirmation</span></p>
        <p class="para">${L.resume}<br><span class="token">--confirm ${esc(s.token || '')}</span></p>`;
      return html;
    }
    if (s.kind === 'done') {
      const v = s.verification;
      return `<p class="k">${L.done}</p><div class="big green">✓ ${L.done}</div>` +
        (v ? `<p class="para">${L.verified}: <span class="pill ok">${d.command === 'desktop' ? L.containsWindow : L.contains} “${esc(d.verifyText || '')}”</span></p>` : '');
    }
    if (s.kind === 'stop') return `<p class="k">${L.stopped}</p><div class="big">${esc(s.status)}</div>`;
    return '';
  }

  function renderReplay(d, s, ph) {
    const L = t();
    const head = `<div class="s-head"><span class="s-logo">Jev <b>Filter</b></span><span class="s-cmd">jev-filter ${d.command}</span>
      <span class="s-goal"><em>${L.goal}</em>${esc(s.goal || d.goal)}</span></div>`;
    if (s.kind === 'intro') {
      return head + `<div class="intro"><h2>${esc(d.title[lang])}</h2><p class="goalq">“${esc(d.goal)}”</p>
        <div class="steps3"><div><b>1</b><p>${L.intro1}</p></div><div><b>2</b><p>${L.intro2}</p></div><div><b>3</b><p>${L.intro3}</p></div></div></div>`;
    }
    if (s.kind === 'outro') {
      const m = d.summary;
      return head + `<div class="intro"><h2>${esc(d.title[lang])}</h2><div class="stats">
        <div><b>${num(m.requests)}</b><span>${L.requests}</span></div><div><b>${num(m.input_tokens)}</b><span>${L.tokens}</span></div>
        <div><b>$${m.input_usd.toFixed(4)}</b><span>${L.cost}</span></div><div><b>${(m.elapsed_ms / 1000).toFixed(1)} ${L.sec}</b><span>${L.time}</span></div></div>
        ${d.slides.some(x => x.kind === 'scene') ? `<p class="para" style="margin-top:10px">${L.both}</p>` : ''}
        <div class="stats" style="grid-template-columns:1fr"><div><b>0</b><span>${L.model}</span></div></div></div>`;
    }
    if (s.kind === 'scene') {
      return head + `<div class="intro"><p class="k">${L.scene}</p><h2>“${esc(s.goal)}”</h2></div>`;
    }
    let overlay = null;
    if (s.kind === 'step' && (ph || !s.decide)) {
      const op = s.decide ? (t().ops[s.decide.operation] || s.decide.operation) : '✓';
      const extra = s.text ? ` <small>← “${esc(s.text)}”</small>` : '';
      overlay = {rect: s.rect, chip: `${op} · ${esc(s.action.label)}${extra}`};
    } else if (s.kind === 'pause') {
      overlay = {rect: s.rect, red: true, chip: `⏸ ${esc(s.pending.label)}`, banner: `⏸ ${L.paused} — ${L.pauseWhy}`, bannerCls: 'red'};
    } else if (s.kind === 'done') {
      overlay = {banner: `✓ ${L.done} — ${L.verified}`, bannerCls: 'green'};
    }
    return head + `<div class="s-body"><div class="s-left">${screen(d, s, overlay)}</div><div class="s-right">${panel(d, s, ph)}</div></div>
      <div class="s-foot">${timeline(d)}${totals(s, d)}</div>`;
  }

  function renderSurvey(d) {
    const L = t().sv, r = d.report, q = r.questions, acc = d.accuracy;
    const head = `<div class="s-head"><span class="s-logo">Jev <b>Filter</b></span><span class="s-cmd">jev-filter survey</span>
      <span class="s-goal"><em>${t().goal}</em>${esc(r.task)}</span></div>`;
    const topics = Object.entries(q.topic.counts).filter(([, n]) => n > 0).sort((a, b) => b[1] - a[1]);
    const topicTotal = topics.reduce((a, [, n]) => a + n, 0);
    const topicBars = bars(topics.map(([k, n]) => ({key: k, name: `${k} · ${n}`, p: n / topicTotal})), null, 't');
    const sent = Object.values(q.sentiment.levels), sentTotal = sent.reduce((a, b) => a + b.count, 0);
    const colors = ['#c8453b', '#9aa8bb', '#1f9d6f'];
    const stack = '<div class="stack">' + sent.map((l, i) => `<div style="width:${l.count / sentTotal * 100}%;background:${colors[i]}">${Math.round(l.count / sentTotal * 100)}%</div>`).join('') + '</div>' +
      '<div style="display:flex;justify-content:space-between;font-size:11.5px;color:#5f6d82">' + sent.map((l, i) => `<span>${esc(L.levels[i] || l.label.split(' or ')[0])}</span>`).join('') + '</div>';
    const cross = Object.entries(r.crosstabs.topic);
    const heat = `<div class="heat" style="grid-template-columns:1.4fr 0.7fr 0.9fr 0.9fr"><div class="hd"></div><div class="hd">${L.n}</div><div class="hd">${L.mean}</div><div class="hd">${L.churnShare}</div>` +
      cross.map(([k, c]) => `<div style="text-align:left">${esc(k)}</div><div style="background:#eef2f7">${c.n}</div>
        <div style="background:rgba(31,157,111,${(c.sentiment_mean / 2).toFixed(2)});color:#172338">${c.sentiment_mean.toFixed(2)}</div>
        <div style="background:rgba(200,69,59,${(c.churn_yes_share * 3).toFixed(2)})">${Math.round(c.churn_yes_share * 100)}%</div>`).join('') + '</div>';
    const quotes = Object.entries(r.representatives.topic).slice(0, 3).map(([k, list]) => `<p class="quote"><b>${esc(k)}</b>${esc(list[0].excerpt)}</p>`).join('');
    const accRows = [['topic', L.topic], ['sentiment', L.sentiment], ['churn', L.churn], ['screen', L.screen]]
      .map(([k, n]) => ({key: k, name: n, p: acc[k].accuracy}));
    return head + `<div class="dash"><div>
      <div class="kpis"><div><b>${num(r.records)}</b><span>${L.records}</span></div><div><b>${num(r.evaluated)}</b><span>${L.kept}</span></div><div><b>${num(r.requests)}</b><span>${L.requests}</span></div>
      <div><b>${(r.elapsed_ms / 1000).toFixed(1)} ${L.sec}</b><span>${L.time}</span></div><div><b>$${r.estimated_input_usd.toFixed(3)}</b><span>${L.usd}</span></div><div><b>${num(r.uncertain_records)}</b><span>${L.uncertain}</span></div></div>
      <div class="card"><h4>${L.topic}</h4>${topicBars}</div>
      <div class="card" style="margin-top:12px"><h4>${L.sentiment}<small>${L.churn}: ${Math.round(q.churn.yes_share * 100)}% ${L.yes}</small></h4>${stack}</div>
    </div><div>
      <div class="card"><h4>${L.byTopic}</h4>${heat}</div>
      <div class="card" style="margin-top:12px"><h4>${L.examples}</h4>${quotes}</div>
      <div class="card" style="margin-top:12px"><h4>${L.accuracy}<small>${L.calib}</small></h4>${bars(accRows, null, 't')}</div>
    </div></div>`;
  }

  function render() {
    const d = DATA.demos[demo];
    const stage = $('stage');
    if (d.kind === 'dashboard') {
      stage.innerHTML = renderSurvey(d);
    } else {
      const s = d.slides[index];
      stage.innerHTML = renderReplay(d, s, phase);
    }
    if (!CAPTURE) {
      $('lede').textContent = t().lede[demo];
      $('play').textContent = playing ? t().pause : t().play;
      $('where').textContent = d.kind === 'dashboard' ? '' : `${t().slide}${index + 1} / ${d.slides.length}`;
      for (const id of ['prev', 'play', 'next']) $(id).hidden = d.kind === 'dashboard';
      document.title = lang === 'zh' ? 'Jev Filter · 录制回放' : 'Jev Filter · recorded runs';
      $('prev').setAttribute('aria-label', lang === 'zh' ? '上一步' : 'Previous');
      $('next').setAttribute('aria-label', lang === 'zh' ? '下一步' : 'Next');
      $('lang').textContent = lang === 'en' ? '中文' : 'English';
      $('notes').innerHTML = `${t().recorded} ${esc(DATA.recorded)}${lang === 'zh' ? '。' : '. '}${t().notes}`;
      $('tabs').innerHTML = Object.keys(DATA.demos).map(k => `<button type="button" data-demo="${k}" class="${k === demo ? 'on' : ''}">${t().tabs[k]}</button>`).join('');
      document.documentElement.lang = lang === 'zh' ? 'zh-CN' : 'en';
      for (const b of $('tabs').querySelectorAll('button')) b.onclick = () => { demo = b.dataset.demo; index = 0; phase = 1; schedule(); render(); };
    }
  }

  function fit() {
    const frame = $('frame'), stage = $('stage');
    const w = CAPTURE ? 1280 : Math.max(frame.clientWidth, 900);
    stage.style.transform = `scale(${w / 1280})`;
    frame.style.height = (720 * w / 1280) + 'px';
  }

  function durations(d) {
    return d.slides.map(s => s.kind === 'step' ? [600, 1500] : s.kind === 'pause' ? [3000] : s.kind === 'done' ? [2800] :
      s.kind === 'intro' ? [3200] : s.kind === 'outro' ? [3400] : [2000]);
  }

  function schedule() {
    clearTimeout(timer);
    const d = DATA.demos[demo];
    if (!playing || CAPTURE || d.kind === 'dashboard') return;
    const dur = durations(d)[index];
    if (dur.length === 2 && phase === 0) { timer = setTimeout(() => { phase = 1; render(); schedule(); }, dur[0]); return; }
    timer = setTimeout(() => {
      index = (index + 1) % d.slides.length;
      phase = d.slides[index].kind === 'step' && d.slides[index].decide ? 0 : 1;
      render(); schedule();
    }, dur[dur.length - 1]);
  }

  function go(delta) {
    const d = DATA.demos[demo];
    if (d.kind === 'dashboard') return;
    index = (index + delta + d.slides.length) % d.slides.length; phase = 1; render(); schedule();
  }

  if (CAPTURE) {
    document.body.classList.add('capture');
    for (const id of ['lede', 'controls', 'notes']) $(id).style.display = 'none';
    document.querySelector('header.page').style.display = 'none';
    document.querySelector('main').style.padding = '0';
    $('frame').style.borderRadius = '0';
    window.__showcase = {
      frames: () => {
        const d = DATA.demos[demo];
        if (d.kind === 'dashboard') return [{i: 0, phase: 1, ms: 4000}];
        const out = [];
        durations(d).forEach((dur, i) => dur.forEach((ms, p) => out.push({i, phase: dur.length === 2 ? p : 1, ms})));
        return out;
      },
      go: (i, ph) => { index = i; phase = ph; render(); return true; },
    };
  } else {
    $('prev').onclick = () => go(-1);
    $('next').onclick = () => go(1);
    $('play').onclick = () => { playing = !playing; schedule(); render(); };
    $('lang').onclick = () => { lang = lang === 'en' ? 'zh' : 'en'; render(); };
    document.addEventListener('keydown', e => { if (e.key === 'ArrowRight') go(1); if (e.key === 'ArrowLeft') go(-1); if (e.key === ' ') { e.preventDefault(); $('play').click(); } });
    window.addEventListener('resize', fit);
  }
  fit();
  render();
  schedule();
})();
